(function(){var L=['A','B','C','D'];var rows=[
[11,'What is the normal processing goal after an event enters Event Management?','Normalize it, deduplicate it, bind it to a CI when possible, and create or update an alert','Create a new platform user representing the monitoring source','Remove CMDB records that did not match the incoming event','Approve a service request associated with the affected application','수신 Event를 정규화·중복 제거하고 가능한 경우 CI에 연결해 Alert를 생성하거나 갱신합니다.'],
[12,'Which event fields commonly distinguish the monitored object and condition?','Source, node, type, resource, metric name, and message key','Monitoring account identifier and assigned platform role','Requested service item and estimated fulfillment cost','Responder survey identifier and submitted response','Source·Node·Type·Resource·Metric·Message Key는 이벤트 정체성과 중복 처리에 중요한 필드입니다.'],
[13,'What does the Source field generally identify?','The monitoring system or integration that produced the event','The affected user group only','The CMDB base table','The remediation password','Source는 이벤트를 보낸 모니터링 시스템이나 통합 출처를 식별합니다.'],
[14,'Why should node values be normalized before CI binding?','Consistent host identifiers improve CMDB matching','They determine dashboard colors','They create MID Servers','They set exam time','호스트명·FQDN·IP 표기가 일관되어야 올바른 CI와 안정적으로 매칭됩니다.'],
[15,'What is the role of the Additional information field?','Carry structured source-specific details used for processing and enrichment','Store all CMDB relationships','Replace the alert table','Hold user passwords','Additional Information은 원천별 부가 데이터를 담아 Rule, Binding, Enrichment에 활용할 수 있습니다.'],
[16,'Which ingestion option is suitable when an external tool sends events through an API?','A supported REST event integration','A client UI policy','A catalog workflow','A transform map for users only','외부 도구는 지원되는 Event API 또는 Connector로 이벤트를 전송할 수 있습니다.'],
[17,'When is a MID Server commonly useful for event collection?','When a connector must run within or reach a protected customer network','When changing workspace branding for Event Management operators','When creating a troubleshooting article for the support organization','When assigning certification enrollment entitlements to learners','보호된 내부 환경의 관리 도구에 Connector가 접근해야 할 때 MID Server가 실행 지점이 됩니다.'],
[18,'What should be verified immediately after enabling a new connector?','Connection status, collection logs, incoming events, and field quality','The number of portal widgets','All user signatures','Catalog pricing','연결 상태와 로그, 실제 Event 유입, 필수 필드 품질을 단계별로 확인합니다.'],
[19,'Why use controlled test events during implementation?','They allow predictable validation without waiting for a production failure','They permanently raise service severity','They delete old alerts','They replace monitoring tools','예상 값을 가진 테스트 이벤트로 Event→Alert 전 처리 경로를 안전하게 검증합니다.'],
[20,'What should happen to an event that is known noise and has no operational value?','Filter or ignore it through a governed event rule','Always create a Critical Incident before evaluating its operational value','Bind it to an arbitrarily selected CI to ensure the field is populated','Modify the class of every candidate CI returned by binding','운영 가치가 없는 노이즈는 검토된 Event Rule로 조기에 필터링합니다.'],
[21,'What can an event rule transform?','Incoming event field values used in alert processing','MID Server operating system files','User passwords','CMDB table inheritance','Event Rule은 Source, Node, Severity 등 수신 필드를 정규화하거나 보강할 수 있습니다.'],
[22,'Why does event-rule order matter?','More than one rule may qualify, so evaluation sequence affects processing','It changes network routing','It sets the browser language','It controls exam scoring','여러 규칙이 조건에 맞을 수 있어 우선순위와 중단 조건이 최종 처리 결과에 영향을 줍니다.'],
[23,'Which practice makes event rules maintainable?','Use clear scope, naming, ownership, test cases, and minimal overlapping conditions','Create many unnamed duplicate rules','Put every source in one untested script','Remove all documentation','명확한 범위·명명·소유권·테스트와 겹치지 않는 조건이 유지보수를 돕습니다.'],
[24,'How should source severities be handled when different tools use different scales?','Map them to a consistent ServiceNow severity model','Store every value as Critical','Ignore all severity fields','Create a CI class per severity','도구별 심각도 체계를 공통 Severity로 명시적으로 매핑해야 우선순위가 일관됩니다.'],
[25,'What is deduplication intended to prevent?','Multiple alerts for repeated observations of the same active condition','Multiple users in one group','Multiple CIs in a service','Multiple dashboards','동일 장애의 반복 Event를 하나의 기존 Alert 갱신으로 처리해 Alert 폭증을 막습니다.'],
[26,'What happens when repeated events have a stable matching message key?','They normally update the corresponding alert rather than create new alerts','They delete the monitoring source','They create new CMDB classes','They disable correlation','안정적인 Message Key는 같은 활성 조건을 기존 Alert로 집계하는 기반입니다.'],
[27,'What is a likely result of including a timestamp in every message key?','Every event may appear unique and create duplicate alerts','CI binding becomes perfect','All alerts close immediately','Incidents cannot be created','매번 바뀌는 Timestamp가 Key에 포함되면 같은 장애도 서로 다른 Alert로 생성될 수 있습니다.'],
[28,'Which design best separates two metrics on the same node?','Include stable metric or resource identity in the message key','Use only the node value as the identity for every monitored condition','Add a different arbitrary value whenever each event is received','Remove source and metric context from the alert identity','같은 Node의 CPU와 Disk 같은 조건은 안정적인 Resource·Metric 식별값으로 구분합니다.'],
[29,'How should a clear or recovery event be designed?','It must match the active condition identity so the correct alert can close','It should use a new arbitrary key unrelated to the active condition','It should target every active alert from the same monitoring source','It should create a new Critical CI to represent the recovered condition','복구 Event가 기존 활성 조건과 동일한 식별 기준으로 매칭되어야 올바른 Alert가 해소됩니다.'],
[30,'What does alert severity represent?','The operational seriousness of the normalized condition','The number of CI attributes','The connector license count','The service owner role','Alert Severity는 정규화된 상태의 운영상 심각성을 표현하며 대응 우선순위에 활용됩니다.'],
[31,'What is implicit node binding?','Matching event node data against host CI attributes such as name, FQDN, IP, or MAC','Creating nodes from incidents','Binding every alert to a business service','Matching user names to groups','기본 Node Binding은 Event Node를 Host CI의 Name·FQDN·IP·MAC 등과 비교합니다.'],
[32,'What format is used by the CI Identifier event field for explicit field matching?','A JSON object containing CI column names and values','An image file','An encrypted PDF','A comma-only user list','CI Identifier는 CI 컬럼과 값을 담은 JSON 구조로 명시적인 매칭 정보를 전달할 수 있습니다.'],
[33,'If node matching fails, what should be reviewed?','Node quality, DNS or identifier data, eligible CI classes, and event processing notes','Workspace navigation preferences of the operator reviewing the event','Certification enrollment records of the Event Management implementer','Knowledge article ratings without node, CI, or processing evidence','Node 값과 CMDB 식별 데이터, 대상 클래스 및 Processing Notes를 통해 실패 경로를 확인합니다.'],
[34,'Why may retired CIs be excluded from binding?','Binding active alerts to decommissioned infrastructure can be misleading','Retired CIs have no names','They cannot exist in CMDB','They always create users','운영 종료된 CI로 현재 Alert가 연결되면 담당과 영향 분석이 잘못될 수 있습니다.'],
[35,'What can an event rule do when default host binding is not appropriate?','Override binding logic to target the intended device or application CI','Disable the CMDB permanently','Change all host names','Create a new company','Event Rule의 Binding 설정으로 기본 Host 대신 적절한 Application·Device CI를 지정할 수 있습니다.'],
[36,'Why bind a process-level alert to an application CI rather than only its host?','It provides more precise ownership and service-impact context','It changes the host IP','It removes the process','It avoids all credentials','애플리케이션 수준 CI 연결은 장애 대상과 담당, 서비스 영향도를 더 정확하게 표현합니다.'],
[37,'Where can clues about CI-binding processing be found on an event?','Processing Notes','User preferences','Catalog variables','Survey metrics','Processing Notes는 어떤 Binding 단계와 Rule이 적용됐는지 조사하는 핵심 단서입니다.'],
[38,'What is the consequence of poor CMDB data for Event Management?','Lower binding accuracy and unreliable service-impact analysis','Faster deduplication','Automatic remediation success','More accurate correlation','부정확하거나 중복된 CI 데이터는 Binding과 토폴로지 기반 영향 분석을 약화시킵니다.'],
[39,'What does alert correlation add beyond deduplication?','Relationships or groups among distinct but related alerts','A new connector source definition for every correlated group','An account credential reset for the responder assigned to the alert','A scheduled CMDB import that replaces alert relationship evaluation','Deduplication은 동일 조건을 합치고, Correlation은 서로 다른 관련 Alert 사이의 관계를 만듭니다.'],
[40,'In a primary-secondary alert relationship, what does the primary alert generally represent?','The likely parent or driving condition for related symptom alerts','The newest user account','The lowest-priority dashboard','The event connector itself','Primary Alert는 관련 증상을 유발하거나 대표하는 상위 조건으로 취급됩니다.'],
[41,'How are rule-based correlation priorities commonly interpreted?','Lower numerical order values are evaluated first','Higher severity always runs last','Alphabetical names decide only','Rules run randomly','Correlation Rule의 낮은 Order 값이 더 높은 평가 우선순위를 가집니다.'],
[42,'Why configure a time window in a correlation rule?','Related alerts should occur close enough in time to support the relationship','It sets user session timeout','It controls discovery schedules','It sets exam duration','시간적으로 가까운 Alert만 관계 후보로 제한해 우연한 상관을 줄입니다.'],
[43,'What does topology-based correlation rely on?','CI relationships that describe infrastructure or service dependencies','Email distribution lists','Catalog categories','User locations only','CMDB와 서비스 맵의 CI 관계를 이용해 부모 장애와 하위 증상 사이의 가능성을 분석합니다.'],
[44,'Why should correlation results be reviewed with operations teams?','Over-grouping can hide independent issues and under-grouping leaves noise','Correlation changes passwords','It deletes all events','It replaces monitoring','과도한 그룹은 별도 장애를 숨기고 부족한 그룹은 노이즈를 남기므로 실제 운영 결과로 튜닝합니다.'],
[45,'Which measure best demonstrates correlation value?','Reduced actionable alert volume without missing independent incidents','More raw events received','More duplicate alerts','More active rules regardless of outcome','독립 장애를 놓치지 않으면서 대응해야 할 Alert 수와 조사 시간을 줄이는지가 핵심입니다.'],
[46,'What can an alert management rule launch?','An incident, task, notification, knowledge action, or remediation subflow','A MID Server installation automatically','A CMDB schema deletion','An exam session','Alert 조건에 따라 Incident·Task·알림·Knowledge·Remediation 같은 대응을 실행할 수 있습니다.'],
[47,'Why should incident-creation rules be selective?','Creating incidents for every alert transfers noise into ITSM','Incidents cannot reference CIs','Alerts never have severity','Rules cannot use conditions','모든 Alert를 Incident로 만들면 Event 노이즈가 ITSM 업무량으로 그대로 전파됩니다.'],
[48,'What should an automated incident include?','Alert, affected CI, service impact, severity, and diagnostic context','Only the name of the rule that initiated Incident creation','Only the user account recorded as the automation actor','Only an unrelated tracking number without alert or CI context','담당자가 즉시 판단할 수 있도록 Alert·CI·영향 서비스·심각도·진단 정보를 전달합니다.'],
[49,'What is remediation in an alert workflow?','A guided or automated action intended to correct the detected condition','A rename of the affected CI class without correcting the detected condition','A report export containing alert statistics but no corrective action','A responder survey submitted instead of executing a recovery procedure','Remediation은 탐지된 상태를 해소하기 위한 자동 또는 안내형 복구 작업입니다.'],
[50,'What safety control is important for automated remediation?','Scope, authorization, validation, timeout, logging, and rollback or escalation handling','An unrestricted administrative service account shared across all remediation targets','Execution without an audit record to reduce processing overhead','Arbitrarily selected targets whenever CI Binding does not return a match','자동 복구에는 대상 범위·권한·검증·Timeout·감사와 실패 시 Rollback 또는 Escalation이 필요합니다.'],
[51,'When should a remediation action be tested?','In a controlled environment with known inputs and success criteria before production use','Only during a major production outage affecting a critical service','After removing execution logs needed to validate its behavior','Without a target CI or defined success and failure conditions','알려진 입력과 성공 기준으로 비운영 환경에서 검증한 후 단계적으로 적용합니다.'],
[52,'What is alert enrichment?','Adding useful CI, service, ownership, or diagnostic context to an alert','Increasing every severity','Creating duplicate events','Changing all CI identifiers','Enrichment은 Alert에 담당·CI·서비스·진단 문맥을 보강해 대응 가능성을 높입니다.'],
[53,'Which enrichment is most useful to an on-call responder?','Actionable ownership, runbook, recent change, and service-impact context','An arbitrarily selected promotional message unrelated to the affected service','A user profile with no ownership or support relationship to the alert','A workspace background image selected by the monitoring administrator','담당자, Runbook, 최근 변경과 영향 서비스 정보는 초기 조사 시간을 단축합니다.'],
[54,'Why monitor connector health separately from service alerts?','A failed connector can create a silent monitoring gap rather than a normal service alert','Connectors are CIs only','It changes event severity','It eliminates deduplication','Connector 장애는 Event 자체가 들어오지 않는 사각지대를 만들 수 있어 별도 상태 감시가 필요합니다.'],
[55,'Which operational KPI helps detect an ingestion outage?','Event volume and last-received time by source compared with a baseline','Workspace page views generated by Event Management operators','The average length of Knowledge articles linked to alerts','The age of a connector service-account credential without ingestion evidence','Source별 Event 유입량과 마지막 수신 시각을 기준선과 비교하면 수집 중단을 빠르게 감지할 수 있습니다.'],
[56,'Which KPI helps evaluate CI binding quality?','The percentage of actionable alerts bound to the correct CI','The number of dashboard colors','The number of user groups','The connector installation date','올바른 CI에 자동 Binding된 Alert 비율과 실패·오연결 비율을 추적합니다.'],
[57,'Which KPI helps evaluate event-noise reduction?','Events-to-alerts ratio, duplicate suppression, and actionable alert rate','Number of CMDB tables','Number of exam questions','Number of browser sessions','Event 대비 Alert 비율, 억제량, 실제 대응 가치가 있는 Alert 비율로 노이즈 감소를 평가합니다.'],
[58,'What is the best response to a sudden alert storm?','Identify the dominant source and key, contain noise safely, then correct the source or processing rule','Remove CMDB records associated with the most frequent alert source','Close alerts in an arbitrary sequence until the queue reaches normal size','Disable every monitoring integration indefinitely without preserving visibility','주요 Source·Key 패턴을 찾아 안전하게 유입을 통제하고 원천 또는 Rule의 근본 원인을 수정합니다.'],
[59,'What should be included in the handoff of an Event Management integration?','Ownership, data contract, rules, tests, monitoring, runbooks, and rollback procedures','Only a connector credential without its owner or rotation process','Only a dashboard link without health thresholds or recovery guidance','Only the source name without field mapping and processing rules','통합 소유권·필드 계약·Rule·테스트·감시·Runbook·Rollback 절차를 운영팀에 인계합니다.'],
[60,'What defines a mature Event Management implementation?','Trusted ingestion, controlled noise, accurate CI context, meaningful correlation, safe automation, and measurable outcomes','The largest possible raw-event volume without measuring actionable outcomes','An Incident created for every event regardless of duplication or operational value','Operation without CMDB context or service-impact relationships','Manual handling of every alert without governed automation or metrics','신뢰할 수 있는 수집부터 노이즈 제어, CI 문맥, 상관분석, 안전한 자동화와 KPI까지 연결되어야 합니다.']
];rows.forEach(function(r){var s=r[0]%4,c=r.slice(2,6),rot=c.slice(s).concat(c.slice(0,s)),correct=L[(4-s)%4];window.CISEM_QUESTIONS.push({id:r[0],title:r[1],options:rot.map(function(t,i){return{id:L[i],text:t}}),answer:[correct],explanation:r[6]})})})();
